import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator 2022-07-26","description":"","frontmatter":{"title":"Ceph Orchestrator 2022-07-26","date":"2022-07-26T00:00:00.000Z","updated":"2022-08-01T00:00:00.000Z","tags":["Ceph","分布式存储","管理标签","Ceph Orchestrator","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_2022-07-26.md","filePath":"posts/2022/Ceph_Orchestrator_2022-07-26.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Orchestrator_2022-07-26.md"};function o(s,e,n,d,h,c){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>管理标签（admin label）功能讨论</strong></p><ul><li>讨论了管理标签在部署<code>ceph.conf</code>和<code>admin keyring</code>文件中的作用，以及移除标签时自动移除这些文件的机制。</li><li>讨论了使用哈希文件来管理这些文件的方法，以确保只有通过特定流程部署的文件才会被移除。</li></ul></li><li><p><strong>NFS Keep Alive功能改进</strong></p><ul><li>讨论了改进NFS Keep Alive功能的命令行参数，提出了使用模式（mode）标志来区分不同的部署策略。</li><li>讨论了如何通过模式标志来管理不同的部署场景，如HA代理模式和Keep Alive Only模式。</li></ul></li><li><p><strong>会议记录归档</strong></p><ul><li>讨论了归档会议记录的重要性，特别是对于长期项目，以避免记录过于庞大导致的管理和加载问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>对于管理标签功能，决定进一步研究使用哈希文件的方法来管理<code>ceph.conf</code>和<code>admin keyring</code>文件。</li><li>对于NFS Keep Alive功能，决定引入模式标志来简化命令行参数，并支持未来的功能扩展。</li><li>决定对会议记录进行定期归档，以保持记录的可管理性和可访问性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>进一步研究和测试管理标签功能的哈希文件方法。</li><li>实施并测试NFS Keep Alive功能的模式标志。</li><li>定期归档会议记录，并更新相关文档和链接。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了关于编译相关PR的处理，决定等待一周以获取反馈，如果无反馈则考虑创建新的PR。</li></ul><p>会议持续了140分钟，涉及了深入的设计和技术讨论。</p><p>[总结内容结束]</p>',11)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
